from pathlib import Path
from docx import Document

docx_path = Path(r"C:\MyPython\AAA_cmip6_analysis_taylor diagram_dailyMonthly\ID1558_revised_for_publication_final.docx")
doc = Document(docx_path)

paras = doc.paragraphs

def find_exact(text):
    for i, p in enumerate(paras):
        if p.text.strip() == text:
            return i
    raise ValueError(f"not found: {text[:80]}")

start_idx = next(i for i, p in enumerate(paras) if p.text.strip().startswith("การทดสอบนัยสำคัญดำเนินการภายในคู่การประเมินแต่ละคู่"))
