template = paras[start_idx]
anchor = paras[start_idx]
inserted = []
for text in new_texts:
    new_p = anchor.insert_paragraph_before(text)
    new_p.style = template.style
    new_p.paragraph_format.left_indent = template.paragraph_format.left_indent
    new_p.paragraph_format.first_line_indent = template.paragraph_format.first_line_indent
    new_p.paragraph_format.space_before = template.paragraph_format.space_before
    new_p.paragraph_format.space_after = template.paragraph_format.space_after
    new_p.paragraph_format.line_spacing = template.paragraph_format.line_spacing
    inserted.append(new_p)

for p in paras[start_idx:end_idx]:
    p._element.getparent().remove(p._element)

doc.save(docx_path)
print(f"replaced methodology inference block paragraphs {start_idx}-{end_idx - 1}")
